package com.narada.connection

import java.util.UUID
import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Test

class DownloadEngineTest {
    @Test fun explicitConsentAndQueueIntentPrecedeAnyRemotePrepare()=runBlocking<Unit>{val f=DownloadFixture();expectFailure("LOCAL_CONFIRMATION_REQUIRED"){runBlocking{f.enqueue(confirmed=false)}};assertTrue(f.memory.document.downloads.isEmpty());val r=f.enqueue();assertEquals(0,f.prepareCount);assertEquals(DownloadState.QUEUED,r.state)}
    @Test fun failedQueuePersistenceCannotSendAnything()=runBlocking<Unit>{val f=DownloadFixture();f.memory.failWrite=true;expectFailure("STORAGE_UNAVAILABLE"){runBlocking{f.enqueue()}};assertEquals(0,f.prepareCount);assertTrue(f.storage.data.isEmpty())}
    @Test fun fullHashAndDurableReceiptAreRequiredForPrivateSuccess()=runBlocking<Unit>{val f=DownloadFixture();val r=f.completed();assertEquals(DownloadState.VERIFIED,r.state);assertEquals(f.bytes.size.toLong(),r.verifiedBytes);assertEquals(sha256(f.bytes),r.receipt!!.sha256);assertEquals(1,f.prepareCount);assertEquals(listOf(0,1,2),f.requested);assertFalse(r.remoteFinished);assertTrue(f.lastBytes!!.all{it==0.toByte()})}
    @Test fun chunkCheckpointFollowsStorageAndFsyncContract()=runBlocking<Unit>{val f=DownloadFixture();f.storage.onWrite={r,i->assertFalse(i in f.record(r.id).chunks)};f.beforeWrite={doc->doc.downloads.forEach{r->r.chunks.forEach{i->assertNotNull(f.storage.data[r.id to i])}}};f.completed()}
    @Test fun diskFullCannotCreateAnOptimisticCheckpoint()=runBlocking<Unit>{val f=DownloadFixture();val r=f.enqueue();f.storage.onWrite={_,_->fail("LOCAL_STORAGE_FULL")};expectFailure("LOCAL_STORAGE_FULL"){runBlocking{f.engine.run(r.id)}};assertTrue(f.record(r.id).chunks.isEmpty());assertNull(f.record(r.id).receipt)}
    @Test fun reserveFailureStopsBeforeSourcePreparation()=runBlocking<Unit>{val f=DownloadFixture();val r=f.enqueue();f.storage.full=true;expectFailure("LOCAL_STORAGE_FULL"){runBlocking{f.engine.run(r.id)}};assertEquals(0,f.prepareCount)}
    @Test fun restartRehashesWrittenButUncheckpointedFragment()=runBlocking<Unit>{val f=DownloadFixture();val r=f.enqueue();f.beforeWrite={if(it.downloads.any{d->d.chunks.isNotEmpty()})fail("STORAGE_UNAVAILABLE")};expectFailure("STORAGE_UNAVAILABLE"){runBlocking{f.engine.run(r.id)}};assertNotNull(f.storage.data[r.id to 0]);assertTrue(f.record(r.id).chunks.isEmpty());f.beforeWrite={};f.engine.recover();assertEquals(DownloadState.PAUSED,f.record(r.id).state);f.engine.queueResume(r.id,true);f.engine.run(r.id);assertEquals(1,f.requested.count{it==0});assertEquals(setOf(r.id),f.preparedIds.toSet())}
    @Test fun lostReceiptWriteNeverReportsSavedAndCanVerifyOfflineAfterRestart()=runBlocking<Unit>{val f=DownloadFixture();val r=f.enqueue();f.beforeWrite={if(it.downloads.any{d->d.receipt!=null})fail("STORAGE_UNAVAILABLE")};expectFailure("STORAGE_UNAVAILABLE"){runBlocking{f.engine.run(r.id)}};assertNull(f.record(r.id).receipt);assertEquals(3,f.record(r.id).chunks.size);f.beforeWrite={};f.engine.recover();f.engine.queueResume(r.id,true);f.onPrepare={fail("PEER_UNREACHABLE")};f.onChunk={_,_->fail("PEER_UNREACHABLE")};assertEquals(DownloadState.VERIFIED,f.engine.run(r.id).state)}
    @Test fun corruptCheckpointBlocksInsteadOfSilentlyReplacingBytes()=runBlocking<Unit>{val f=DownloadFixture();val r=f.enqueue();f.onChunk={_,i->if(i==1)fail("PEER_TIMEOUT")};expectFailure{runBlocking{f.engine.run(r.id)}};f.storage.data[r.id to 0]!![0]=99;f.engine.recover();f.engine.queueResume(r.id,true);expectFailure("LOCAL_COPY_CHANGED"){runBlocking{f.engine.run(r.id)}};assertNull(f.record(r.id).receipt);assertEquals(99,f.storage.data[r.id to 0]!![0].toInt());assertEquals(DownloadState.CORRUPT,f.record(r.id).state);assertEquals(0L,f.record(r.id).verifiedBytes)}
    @Test fun missingCheckpointIsNotCountedAndUsesTheSameTransferOnResume()=runBlocking<Unit>{val f=DownloadFixture();val r=f.enqueue();f.onChunk={_,i->if(i==1)fail("PEER_TIMEOUT")};expectFailure{runBlocking{f.engine.run(r.id)}};f.storage.data.remove(r.id to 0);f.engine.recover();f.onChunk={_,_->};f.engine.queueResume(r.id,true);f.engine.run(r.id);assertEquals(2,f.requested.count{it==0});assertEquals(setOf(r.id),f.preparedIds.toSet())}
    @Test fun wrongNetworkChunkNeverTouchesPrivateStorage()=runBlocking<Unit>{val f=DownloadFixture();val r=f.enqueue();f.transform={it.apply{this[0]=0}};expectFailure("HASH_MISMATCH"){runBlocking{f.engine.run(r.id)}};assertEquals(0,f.storage.writes);assertTrue(f.lastBytes!!.all{it==0.toByte()})}
    @Test fun emptyFileStillRequiresAnExactManifestAndPrivateReceipt()=runBlocking<Unit>{val f=DownloadFixture(byteArrayOf());val r=f.completed();assertTrue(f.requested.isEmpty());assertEquals(0L,r.receipt!!.size);assertEquals(sha256(byteArrayOf()),r.receipt.sha256)}
    @Test fun transientFailureHasNoHiddenAutomaticRetry()=runBlocking<Unit>{val f=DownloadFixture();val r=f.enqueue();f.onChunk={_,_->fail("PEER_TIMEOUT")};expectFailure("PEER_TIMEOUT"){runBlocking{f.engine.run(r.id)}};assertEquals(1,f.requested.size);assertNull(f.record(r.id).receipt)}
    @Test fun recoveredQueueCannotRunWithoutExplicitResume()=runBlocking<Unit>{val f=DownloadFixture();val r=f.enqueue();f.engine.recover();assertEquals(DownloadState.PAUSED,f.record(r.id).state);expectFailure("TRANSFER_STOPPED"){runBlocking{f.engine.run(r.id)}};expectFailure("LOCAL_CONFIRMATION_REQUIRED"){runBlocking{f.engine.queueResume(r.id,false)}};assertEquals(0,f.prepareCount)}
    @Test fun localCancelRetainsFragmentsAndCannotUndoTheDesktop()=runBlocking<Unit>{val f=DownloadFixture();val r=f.enqueue();f.onChunk={_,i->if(i==1)fail("PEER_TIMEOUT")};expectFailure{runBlocking{f.engine.run(r.id)}};f.engine.pause(r.id);f.engine.cancel(r.id,true);assertEquals(DownloadState.CANCELLED,f.record(r.id).state);assertTrue(f.storage.data.isNotEmpty());assertEquals(0,f.storage.removals);assertEquals(0,f.finishCount)}
    @Test fun privateRemovalRequiresConsentAndCannotRemoveAnUncertainExport()=runBlocking<Unit>{val f=DownloadFixture();val r=f.completed();expectFailure("LOCAL_CONFIRMATION_REQUIRED"){runBlocking{f.engine.remove(r.id,false)}};f.memory.document=f.memory.document.replaceDownload(r.copy(exports=listOf(ExportRecord(UUID.randomUUID().toString(),"copy.bin",r.createdAt,state=ExportState.UNCERTAIN))));expectFailure("EXPORT_UNRESOLVED"){runBlocking{f.engine.remove(r.id,true)}};assertTrue(f.storage.data.isNotEmpty())}
    @Test fun explicitPrivateRemovalDeletesOnlyThatOwnedJob()=runBlocking<Unit>{val f=DownloadFixture();val r=f.completed();f.storage.data[UUID.randomUUID().toString() to 0]=byteArrayOf(9);f.engine.remove(r.id,true);assertTrue(f.memory.document.downloads.isEmpty());assertEquals(1,f.storage.data.size)}
    @Test fun lateChunkCannotCrossADurablePauseToken()=runBlocking<Unit>{val f=DownloadFixture();val r=f.enqueue();f.onChunk={request,_->f.memory.document=f.memory.document.replaceDownload(f.record(request.id).copy(state=DownloadState.PAUSED,runId=null))};expectFailure("TRANSFER_STOPPED"){runBlocking{f.engine.run(r.id)}};assertEquals(0,f.storage.writes);assertTrue(f.lastBytes!!.all{it==0.toByte()})}
    @Test fun missingSavedCopyDemotesReceiptBeforeAnyExport()=runBlocking<Unit>{val f=DownloadFixture();val r=f.completed();f.storage.data.remove(r.id to 0);expectFailure("LOCAL_COPY_MISSING"){runBlocking{f.engine.verifyPrivate(r.id)}};assertEquals(DownloadState.CORRUPT,f.record(r.id).state);assertEquals(0L,f.record(r.id).verifiedBytes)}
    @Test fun lostFinishAckDoesNotUndoLocalReceiptAndExactRetryIsExplicit()=runBlocking<Unit>{val f=DownloadFixture();val r=f.completed();f.onFinish={fail("PEER_TIMEOUT")};expectFailure("PEER_TIMEOUT"){runBlocking{f.engine.finish(r.id)}};assertEquals(DownloadState.VERIFIED,f.record(r.id).state);assertFalse(f.record(r.id).remoteFinished);f.onFinish={};f.engine.finish(r.id);assertTrue(f.record(r.id).remoteFinished);assertEquals(2,f.finishCount)}
    @Test fun queueCountAndByteQuotaNeverEvictExistingCopies()=runBlocking<Unit>{
        suspend fun distinct(f:DownloadFixture,size:Long=f.bytes.size.toLong())=f.engine.enqueue(f.peer.id,f.peer.attemptId,TransferSamples.source.copy(object_id=UUID.randomUUID().toString()),"ordinary.bin",size,true)
        val f=DownloadFixture();repeat(4){distinct(f)};expectFailure("TRANSFER_LOCAL_QUOTA"){runBlocking{distinct(f)}};assertEquals(4,f.memory.document.downloads.size)
        val other=DownloadFixture();repeat(2){distinct(other,TransferRules.MAX_BYTES)};expectFailure("TRANSFER_LOCAL_QUOTA"){runBlocking{distinct(other,1)}};assertEquals(2,other.memory.document.downloads.size)
    }
    @Test fun wholeFileHashIsIndependentOfValidPerChunkHashes()=runBlocking<Unit>{val f=DownloadFixture();val bad=f.bundle.manifest.copy(sha256="b".repeat(64));val bundle=ManifestBundle(bad.copy(manifest_id=bad.digest(f.bundle.hashes)),f.bundle.hashes);val gateway=object:TransfersGateway by f.gateway{override suspend fun prepare(record:DownloadRecord)=bundle};val engine=DownloadEngine(f.repository,gateway,f.storage);val r=f.enqueue();expectFailure("HASH_MISMATCH"){runBlocking{engine.run(r.id)}};assertNull(f.record(r.id).receipt);assertEquals(0,f.finishCount)}
}
